-- core/data.lua: the selected build's API lists (data/forever-<build>/,
-- generated by tools/gen_data.lua from that build's dump).

local cache = {}
local FILES = { widgetMethods = "widget-methods.txt", functions = "functions.txt",
                globals = "globals.txt", events = "events.txt" }

-- Kit.data(kind) -> a set (name -> true). kind: widgetMethods, functions,
-- globals or events. A missing or empty list is an error, never an empty set:
-- a check against nothing would pass everything.
function Kit.data(kind)
    if cache[kind] then return cache[kind] end
    local file = assert(FILES[kind], "unknown data kind " .. tostring(kind))
    local path = Kit.ROOT .. "/data/forever-" .. Kit.BUILD .. "/" .. file
    local f = io.open(path, "r")
    if not f then
        error("WowTestKit has no " .. file .. " for build " .. Kit.BUILD .. " (" .. path .. "): "
            .. "pick a build the kit has (data/), or generate it (tools/gen_data.lua)", 0)
    end
    local set, n = {}, 0
    for line in f:lines() do
        line = line:gsub("\r$", "")
        if line ~= "" and not line:match("^#") then set[line] = true; n = n + 1 end
    end
    f:close()
    if n == 0 then error(path .. " is empty", 0) end
    cache[kind] = set
    return set
end

-- The builds this kit has data for, oldest first, and whether a newer one than
-- the selected build exists (the runners print a notice; the workspace rule
-- is to test against the newest).
function Kit.builds()
    local list = {}
    local sep = package.config:sub(1, 1)
    local cmd = sep == "\\" and ('dir /b "' .. (Kit.ROOT .. "/data"):gsub("/", "\\") .. '" 2>nul')
        or ("ls '" .. Kit.ROOT .. "/data' 2>/dev/null")
    local p = io.popen(cmd)
    if p then
        for name in p:lines() do
            local b = name:match("^forever%-(%d+)%s*$")
            if b then list[#list + 1] = b end
        end
        p:close()
    end
    table.sort(list, function(a, b) return tonumber(a) < tonumber(b) end)
    return list
end

function Kit.newerBuild()
    local list = Kit.builds()
    local newest = list[#list]
    if newest and tonumber(newest) > tonumber(Kit.BUILD) then return newest end
end
